targets=[B,C,D]
flat=A.ravel()
for kind in ['py_seq','np_rs_seq','np_gen_seq']:
    matches=[]
    for seed in range(10000):
        if kind=='py_seq':
            r=random.Random(seed); outs=[]
            for _ in range(3):
                ix=list(range(25)); r.shuffle(ix); outs.append(flat[ix].reshape(5,5))
        elif kind=='np_rs_seq':
            r=np.random.RandomState(seed); outs=[flat[r.permutation(25)].reshape(5,5) for _ in range(3)]
        else:
            r=np.random.default_rng(seed); outs=[flat[r.permutation(25)].reshape(5,5) for _ in range(3)]
        if all(np.array_equal(o,t) for o,t in zip(outs,targets)): matches.append(seed)
    print(kind,matches[:5],len(matches))
